window.COURS_INDEX = [{"chapter":"Entiers & décimaux","title":"Vue d'ensemble","level":"6ème","desc":"Un prix de 12,35 €, un temps de 9,58 s, une taille de 1,72 m : les nombres décimaux sont partout. Ce livre apprend à les lire vraiment (que vaut chaque chiffre ?), à les comparer, à les arrondir, puis à poser les quatre opérations sans jamais perdre la virgule.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Entiers & décimaux","title":"Lire et écrire les nombres","level":"6ème","desc":"Dans 687, le 6 vaut 600, le 8 vaut 80, le 7 vaut 7. Le même chiffre 6 dans 68 ne vaut que 60 : c'est sa position qui décide.","duration":"5 pages","bilan":false,"competence":1,"familles":["Chiffre et nombre","Écrire un grand nombre en chiffres"]},{"chapter":"Entiers & décimaux","title":"Comparer et ranger des décimaux","level":"6ème","desc":"À première vue, 68 est plus grand que 7. Mais 3,7, c'est 3,70 : 70 centièmes. Et 3,68, c'est 68 centièmes. 70 > 68, donc 3,7 > 3,68.","duration":"4 pages","bilan":false,"competence":2,"familles":["Comparer deux décimaux","Ranger des décimaux","Intercaler un décimal"]},{"chapter":"Entiers & décimaux","title":"Encadrer et arrondir","level":"6ème","desc":"7,83 est entre 7 et 8 : 7 < 7,83 < 8. C'est un encadrement à l'unité.","duration":"4 pages","bilan":false,"competence":3,"familles":["Encadrer","Arrondir un décimal"]},{"chapter":"Entiers & décimaux","title":"Multiplier et diviser par 10, 100, 1000","level":"6ème","desc":"3,25 × 10 : chaque chiffre vaut dix fois plus, il monte d'une place. Les 3 unités deviennent 3 dizaines, les 2 dixièmes deviennent 2 unités… On obtient 32,5.","duration":"4 pages","bilan":false,"competence":4,"familles":["Multiplier par 10,100,1000 etc...","Diviser par 10,100,1000 etc..."]},{"chapter":"Entiers & décimaux","title":"Poser une addition ou une soustraction","level":"6ème","desc":"12,5 + 3,78. Si on aligne les chiffres à droite, on additionne des dixièmes (5) avec des centièmes (8) : faux.","duration":"4 pages","bilan":false,"competence":5,"familles":["Addition posée de décimaux","Soustraction posée de décimaux"]},{"chapter":"Entiers & décimaux","title":"Multiplier des décimaux","level":"6ème","desc":"2,4 × 0,3. On multiplie comme des entiers : 24 × 3 = 72.","duration":"4 pages","bilan":false,"competence":6,"familles":["Multiplication de décimaux"]},{"chapter":"Entiers & décimaux","title":"Diviser un décimal","level":"6ème","desc":"7,5 L de jus pour 6 verres. 7 ÷ 6 = 1, reste 1 : chaque verre reçoit 1 L, il reste 1 L, soit 10 dixièmes, plus les 5 dixièmes : 15 dixièmes.","duration":"4 pages","bilan":false,"competence":7,"familles":["Division décimale"]},{"chapter":"Entiers & décimaux","title":"Résoudre un problème","level":"6ème","desc":"La monnaie du libraire : un livre coûte 12,35 €, tu donnes 20 €. Combien te rend-il ?","duration":"4 pages · animé","bilan":false,"competence":8,"familles":["La monnaie du libraire","Le plein de carburant"]},{"chapter":"Entiers & décimaux","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Fractions","title":"Vue d'ensemble","level":"6ème–4ème","desc":"Une pizza coupée en huit, un réservoir aux deux tiers, un ruban à partager en quarts : les fractions décrivent tous les partages. Ce livre les fait voir, explique pourquoi les règles marchent, et s'entraîne sur des situations réelles.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Fractions","title":"Comprendre une fraction","level":"6ème","desc":"Huit amis se partagent une pizza. Pour que ce soit juste, on la coupe en 8 parts ÉGALES. Chacun reçoit une part : un huitième, noté 1/8.","duration":"5 pages · animé","bilan":false,"competence":1,"familles":["Fraction d'une figure","Le gâteau partagé"]},{"chapter":"Fractions","title":"Prendre une fraction d'une quantité","level":"6ème","desc":"La jauge dit que le réservoir de 45 litres est rempli aux 2/3. Combien de litres ?","duration":"5 pages · animé","bilan":false,"competence":2,"familles":["Fraction d'une quantité","La jauge du réservoir"]},{"chapter":"Fractions","title":"Écriture décimale et encadrement","level":"6ème","desc":"3 pizzas pour 4 amis. Chacun reçoit 3/4 de pizza. Combien est-ce, en nombre ? 3 ÷ 4 = 0,75 pizza.","duration":"5 pages","bilan":false,"competence":3,"familles":["Écriture décimale d'une fraction","Encadrer une fraction"]},{"chapter":"Fractions","title":"Fractions égales et simplification","level":"5ème","desc":"Une demi-pizza : 1/2. Coupe chaque moitié en deux : tu as 4 parts, et la demi-pizza en fait 2. C'est 2/4. La même quantité.","duration":"5 pages · animé","bilan":false,"competence":4,"familles":["Fractions égales","Simplifier des fractions"]},{"chapter":"Fractions","title":"Comparer des fractions","level":"5ème","desc":"5/7 et 4/7 : ce sont des parts de la même taille, des septièmes. Cinq parts, c'est plus que quatre.","duration":"5 pages","bilan":false,"competence":5,"familles":["Comparer"]},{"chapter":"Fractions","title":"Additionner et soustraire des fractions","level":"5ème–4ème","desc":"2/9 de tarte au déjeuner, 5/9 au dîner. En tout ? Des neuvièmes plus des neuvièmes : 2 + 5 = 7 parts. 2/9 + 5/9 = 7/9.","duration":"5 pages","bilan":false,"competence":6,"familles":["Additionner avec le même dénominateur","Additionner avec des dénominateurs multiples","Somme de dénominateurs quelconques","Différence de fractions","Somme avec un relatif"]},{"chapter":"Fractions","title":"Multiplier des fractions","level":"4ème","desc":"Il reste la moitié d'un gâteau. Tu en manges les 2/3. Quelle fraction du gâteau entier as-tu mangée ?","duration":"5 pages · animé","bilan":false,"competence":7,"familles":["Produit de fractions","Fraction d'une fraction","Produit avec un signe","Opérations entiers et fractions"]},{"chapter":"Fractions","title":"Inverse et division","level":"4ème","desc":"L'inverse de 3/5 est 5/3 : 3/5 × 5/3 = 15/15 = 1. On échange le haut et le bas.","duration":"5 pages","bilan":false,"competence":8,"familles":["L'inverse d'un nombre","Quotient de fractions"]},{"chapter":"Fractions","title":"Priorités et parenthèses","level":"4ème","desc":"1/2 + 1/2 × 3 : la multiplication passe avant l'addition. 1/2 × 3 = 3/2. Puis 1/2 + 3/2 = 4/2 = 2.","duration":"3 pages","bilan":false,"competence":9,"familles":["Priorités avec des fractions","Expression avec parenthèses"]},{"chapter":"Fractions","title":"Résoudre un problème","level":"5ème–4ème","desc":"Dans un problème de partage, le tout (le gâteau, le trajet, le budget) vaut 1. Les fractions prises s'additionnent ; ce qui reste est le complément à 1.","duration":"4 pages","bilan":false,"competence":10,"familles":["La randonnée en deux étapes","Les brioches du goûter","Les sachets de café","Le terrain partagé"]},{"chapter":"Fractions","title":"Bilan du chapitre","level":"6ème–4ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"6 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Nombres relatifs","title":"Vue d'ensemble","level":"5ème–4ème","desc":"Un congélateur à −18 °C, un parking au niveau −2, un compte en banque dans le rouge, la mer Morte à −430 m : dès qu'une grandeur peut descendre sous zéro, il faut des nombres négatifs. Ce livre les fait voir sur un thermomètre, un ascenseur et un relevé de compte, puis explique pourquoi les règles de calcul sont ce qu'elles sont.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Nombres relatifs","title":"Repérer et ranger des relatifs","level":"5ème","desc":"Un thermomètre marque 0 °C quand l'eau gèle. Mais il fait parfois plus froid : on a besoin de nombres EN DESSOUS de zéro. On écrit −5 °C : cinq degrés sous zéro.","duration":"5 pages · animé","bilan":false,"competence":1,"familles":["Ranger des relatifs","L'opposé d'un nombre","La température du congélateur"]},{"chapter":"Nombres relatifs","title":"Distance entre deux points","level":"5ème","desc":"Le congélateur est à −18 °C, le frigo à +4 °C. De combien de degrés faut-il réchauffer un aliment qui passe de l'un à l'autre ?","duration":"5 pages","bilan":false,"competence":2,"familles":["Distance entre deux points"]},{"chapter":"Nombres relatifs","title":"Additionner et soustraire","level":"5ème","desc":"Tu es au niveau −2 du parking. L'ascenseur monte de 5 étages : tu arrives au 3e. −2 + 5 = +3.","duration":"5 pages · animé","bilan":false,"competence":3,"familles":["Suite d'additions et de soustractions","Simplifier une opération","L'ascenseur du parking","Le compte en banque"]},{"chapter":"Nombres relatifs","title":"Multiplier et diviser","level":"4ème","desc":"3 × (−4) : trois fois une dette de 4, c'est une dette de 12. 3 × (−4) = −12.","duration":"5 pages · animé","bilan":false,"competence":4,"familles":["Produits de relatifs","Quotients de relatifs","La règle des signes en chaîne"]},{"chapter":"Nombres relatifs","title":"Priorités avec des relatifs","level":"4ème","desc":"3 − 2 × (−4) : la multiplication d'abord, comme toujours. 2 × (−4) = −8.","duration":"4 pages","bilan":false,"competence":5,"familles":["Priorité des relatifs"]},{"chapter":"Nombres relatifs","title":"Résoudre un problème","level":"5ème–4ème","desc":"Un quiz : +3 points par bonne réponse, −2 par mauvaise. Léa a 6 bonnes réponses et 5 mauvaises. Son score ?","duration":"4 pages · animé","bilan":false,"competence":6,"familles":["La dette partagée","Les points du quiz"]},{"chapter":"Nombres relatifs","title":"Bilan du chapitre","level":"5ème–4ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Puissances","title":"Vue d'ensemble","level":"4ème–3ème","desc":"Une bactérie qui se dédouble chaque heure, la distance d'une étoile en kilomètres, la taille d'un virus en mètres : les puissances écrivent en trois signes ce qui prendrait une ligne. Ce livre part du doublement, explique chaque règle, et finit sur l'écriture scientifique.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Puissances","title":"Calculer une puissance","level":"4ème","desc":"Un grain de riz sur la première case, deux sur la deuxième, quatre sur la troisième : on double à chaque case. Case 7 : 2 × 2 × 2 × 2 × 2 × 2 = 64 grains.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Calculer une puissance"]},{"chapter":"Puissances","title":"Puissances de 10 et écriture scientifique","level":"4ème","desc":"10² = 100, 10³ = 1 000, 10⁶ = 1 000 000. Une puissance de 10 s'écrit 1 suivi d'autant de zéros que l'exposant.","duration":"4 pages","bilan":false,"competence":2,"familles":["Puissances de 10"]},{"chapter":"Puissances","title":"Exposant négatif","level":"4ème","desc":"2³ = 8, 2² = 4, 2¹ = 2, 2⁰ = 1. À chaque cran, on divise par 2. Continuons : 2⁻¹ = 1/2, 2⁻² = 1/4, 2⁻³ = 1/8.","duration":"4 pages","bilan":false,"competence":3,"familles":["Exposant négatif"]},{"chapter":"Puissances","title":"Produit et quotient de puissances","level":"4ème–3ème","desc":"2³ × 2² = (2 × 2 × 2) × (2 × 2) = 2 × 2 × 2 × 2 × 2 = 2⁵. Trois facteurs plus deux facteurs font cinq facteurs.","duration":"4 pages","bilan":false,"competence":4,"familles":["Produit et quotient de puissances"]},{"chapter":"Puissances","title":"Puissances et parenthèses","level":"4ème","desc":"(−2)⁴ : le signe est DANS les parenthèses, il fait partie de la base. (−2) × (−2) × (−2) × (−2) : quatre négatifs, résultat positif, 16.","duration":"4 pages","bilan":false,"competence":5,"familles":["Puissances et parenthèses"]},{"chapter":"Puissances","title":"Résoudre un problème","level":"4ème–3ème","desc":"Une bactérie se dédouble toutes les heures. Au départ, une seule. Après 1 h : 2. Après 2 h : 4. Après 6 h : 2⁶ = 64 bactéries. Après 24 h : 2²⁴ ≈ 16,8 millions.","duration":"4 pages · animé","bilan":false,"competence":6,"familles":["Les bactéries qui doublent","Les globules rouges","L'étoile à 4 années-lumière"]},{"chapter":"Puissances","title":"Bilan du chapitre","level":"4ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Proportionnalité","title":"Vue d'ensemble","level":"6ème–3ème","desc":"Le prix au kilo, la vitesse d'une voiture, l'échelle d'une carte, la recette pour neuf personnes : quand une grandeur double, l'autre double. Ce livre apprend à reconnaître cette régularité, à s'en servir avec plusieurs méthodes, et à ne pas la voir là où elle n'est pas.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Proportionnalité","title":"Reconnaître une situation de proportionnalité","level":"5ème","desc":"2 places coûtent 16 €, 5 places coûtent 40 €, 10 places coûtent 80 €. Chaque fois, prix ÷ places = 8 : une place coûte 8 €, quel que soit le nombre acheté.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Reconnaître la proportionnalité","Le tarif est-il proportionnel ?"]},{"chapter":"Proportionnalité","title":"Compléter un tableau de proportionnalité","level":"6ème","desc":"4 cahiers coûtent 6 €. Combien pour 10 cahiers ?","duration":"5 pages","bilan":false,"competence":2,"familles":["Compléter un tableau de proportionnalité","La méthode additive","La recette pour 9 personnes"]},{"chapter":"Proportionnalité","title":"Le produit en croix","level":"5ème","desc":"Dans un tableau de proportionnalité, 4 → 10 et 6 → 15 (coefficient 2,5). Multiplie en croix : 4 × 15 = 60 et 10 × 6 = 60. Égaux !","duration":"4 pages","bilan":false,"competence":3,"familles":["Le produit en croix 1"]},{"chapter":"Proportionnalité","title":"Échelles et agrandissements","level":"5ème","desc":"Échelle 1 : 50 000. Cela signifie : 1 cm sur la carte = 50 000 cm dans la réalité. Toutes les longueurs de la carte sont 50 000 fois plus petites que les vraies.","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Utiliser une échelle de carte","La photo agrandie","La maquette au 1/24"]},{"chapter":"Proportionnalité","title":"Partager selon un ratio","level":"5ème","desc":"Lina et Sam se partagent 63 € dans le ratio 2 : 5. Cela veut dire : chaque fois que Lina reçoit 2 parts, Sam en reçoit 5.","duration":"3 pages","bilan":false,"competence":5,"familles":["Partager selon un ratio"]},{"chapter":"Proportionnalité","title":"Vitesse, distance et durée","level":"4ème","desc":"Une voiture roule à 90 km/h : elle parcourt 90 km chaque heure. En 2 h, 180 km. En 3 h, 270 km. La distance est proportionnelle au temps, et la vitesse est le coefficient.","duration":"4 pages · animé","bilan":false,"competence":6,"familles":["Vitesse moyenne","Calculer une distance","Calculer une durée","Le coureur régulier","La moyenne sur tout le trajet"]},{"chapter":"Proportionnalité","title":"Débit et masse volumique","level":"3ème","desc":"Un robinet remplit un seau de 60 L en 4 min. Son débit : 60 ÷ 4 = 15 L/min. Chaque minute, 15 litres de plus. Le volume est proportionnel au temps.","duration":"3 pages · animé","bilan":false,"competence":7,"familles":["Calculer un débit","Masse volumique"]},{"chapter":"Proportionnalité","title":"Résoudre un problème","level":"6ème–5ème","desc":"1. Est-ce proportionnel ? (Un prix au kilo, oui. Un abonnement plus un prix à l'unité, non.)","duration":"3 pages","bilan":false,"competence":8,"familles":["Le sirop à diluer","La recette pour 9 personnes"]},{"chapter":"Proportionnalité","title":"Bilan du chapitre","level":"6ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Pourcentages","title":"Vue d'ensemble","level":"6ème–3ème","desc":"« −30 % », « TVA 20 % », « 40 % des élèves » : un pourcentage est une part de cent. Ce livre explique ce que ça veut dire, comment le calculer dans les deux sens, puis comment enchaîner hausses et baisses sans se tromper.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Pourcentages","title":"Exprimer une proportion en pourcentage","level":"5ème","desc":"40 %, c'est « 40 pour cent » : sur 100, on en prend 40. C'est la fraction 40/100, le nombre décimal 0,40.","duration":"4 pages","bilan":false,"competence":1,"familles":["Pourcentage d'une proportion","Exprimer en pourcentage"]},{"chapter":"Pourcentages","title":"Appliquer un pourcentage","level":"6ème–4ème","desc":"20 % de 150 : on prend 20 pour chaque 100. Dans 150, il y a 1,5 fois 100, donc 20 × 1,5 = 30.","duration":"4 pages","bilan":false,"competence":2,"familles":["Appliquer un pourcentage"]},{"chapter":"Pourcentages","title":"Calculer une augmentation ou une remise","level":"4ème","desc":"Un jean coûte 60 €, il est soldé à −30 %. La remise porte sur le prix : 30 % de 60 = 18 €.","duration":"4 pages","bilan":false,"competence":3,"familles":["Calculer une augmentation","Calculer une remise","La hausse du ticket","La remise du magasin de sport"]},{"chapter":"Pourcentages","title":"Les coefficients multiplicateurs","level":"3ème","desc":"Augmenter un prix de 35 %, c'est garder 100 % du prix et ajouter 35 % : on obtient 135 % du prix. Et 135 % = 1,35. Le nouveau prix est l'ancien × 1,35.","duration":"4 pages","bilan":false,"competence":4,"familles":["Coefficients multiplicateurs","Appliquer une baisse","Du HT au TTC"]},{"chapter":"Pourcentages","title":"Calculer un taux d'évolution","level":"3ème","desc":"Un prix passe de 80 € à 92 €. Variation : 92 − 80 = 12 €. Par rapport au prix de départ : 12 ÷ 80 = 0,15. Taux d'évolution : +15 %.","duration":"4 pages","bilan":false,"competence":5,"familles":["Calculer un taux d'évolution"]},{"chapter":"Pourcentages","title":"Résoudre un problème","level":"4ème","desc":"Article A : 60 € à −30 %. Article B : 55 € à −20 %. Lequel est le moins cher après remise ?","duration":"3 pages","bilan":false,"competence":6,"familles":["Le comparateur de soldes"]},{"chapter":"Pourcentages","title":"Bilan du chapitre","level":"6ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Longueur","title":"Vue d'ensemble","level":"6ème","desc":"Une carte en kilomètres, un plan en centimètres, une bouteille en litres et un bac en centimètres cubes : les mesures ne parlent pas toujours la même langue. Ce livre apprend à convertir les longueurs, les aires et les volumes, et explique pourquoi les règles diffèrent.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Longueur","title":"Convertir des longueurs","level":"6ème","desc":"Les unités de longueur, de la plus grande à la plus petite : kilomètre, hectomètre, décamètre, mètre, décimètre, centimètre, millimètre. Chacune vaut 10 fois la suivante : 1 m = 10 dm = 100 cm = 1 000 mm.","duration":"4 pages","bilan":false,"competence":1,"familles":["Convertir des longueurs"]},{"chapter":"Longueur","title":"Comparer des longueurs","level":"6ème","desc":"0,8 km, 750 m ou 82 000 cm : lequel est le plus long ? Les nombres seuls ne disent rien : 82 000 est le plus grand, mais ce sont des centimètres.","duration":"3 pages","bilan":false,"competence":2,"familles":["Comparer des longueurs"]},{"chapter":"Longueur","title":"Convertir et comparer des surfaces","level":"6ème","desc":"Un carré de 1 m de côté. Combien de carrés de 1 dm de côté dedans ? 10 sur la longueur, 10 sur la largeur : 10 × 10 = 100. Donc 1 m² = 100 dm².","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Convertir des surfaces","Comparer des surfaces"]},{"chapter":"Longueur","title":"Convertir et comparer des volumes","level":"6ème","desc":"Un cube de 1 dm d'arête. Combien de cubes de 1 cm dedans ? 10 sur la longueur, 10 sur la largeur, 10 en hauteur : 10 × 10 × 10 = 1 000. Donc 1 dm³ = 1 000 cm³.","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Convertir des volumes","Comparer des volumes"]},{"chapter":"Longueur","title":"Résoudre un problème","level":"6ème","desc":"Un ruban de 2,4 m est coupé en morceaux de 30 cm. Combien de morceaux ? Diviser 2,4 par 30 n'a pas de sens : ce ne sont pas les mêmes unités.","duration":"3 pages","bilan":false,"competence":5,"familles":["Le ruban à partager"]},{"chapter":"Longueur","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Aires et figures","title":"Vue d'ensemble","level":"6ème","desc":"Clôturer un jardin ou le recouvrir de pelouse, ce sont deux questions différentes : le périmètre (le tour) et l'aire (la surface). Ce livre distingue les deux, retrouve chaque formule au lieu de la réciter, et l'applique aux figures usuelles.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Aires et figures","title":"Reconnaître une figure","level":"6ème","desc":"Un rectangle a quatre angles droits. Un losange a quatre côtés de même longueur. Un carré a les deux : quatre angles droits ET quatre côtés égaux. Un carré est donc un rectangle particulier, et un losange particulier.","duration":"3 pages · animé","bilan":false,"competence":1,"familles":["Reconnaître une figure"]},{"chapter":"Aires et figures","title":"Aire et périmètre du carré","level":"6ème","desc":"Un carré de 6 cm de côté. Le PÉRIMÈTRE, c'est la longueur du tour : 6 + 6 + 6 + 6 = 4 × 6 = 24 cm. C'est ce qu'il faut de ruban pour en faire le tour.","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Aire et périmètre d'un carré"]},{"chapter":"Aires et figures","title":"Aire et périmètre du rectangle","level":"6ème","desc":"Un rectangle de 7 cm de long et 3 cm de large. Recouvre-le de carreaux de 1 cm : 3 rangées de 7 carreaux, 7 × 3 = 21 carreaux. Aire : 21 cm².","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Aire et périmètre d'un rectangle"]},{"chapter":"Aires et figures","title":"Aire et périmètre du triangle","level":"6ème","desc":"Prends un rectangle 4 × 3 et coupe-le par sa diagonale : deux triangles rectangles identiques. Chacun a une aire moitié : 4 × 3 ÷ 2 = 6 cm².","duration":"4 pages","bilan":false,"competence":4,"familles":["Aire et périmètre d'un triangle rectangle","Aire et périmètre d'un triangle quelconque"]},{"chapter":"Aires et figures","title":"Aire et périmètre du cercle","level":"6ème","desc":"Mesure le tour d'une assiette avec un mètre ruban, puis son diamètre. Divise : tu trouves toujours à peu près 3,14. Quel que soit le cercle. Ce rapport est le nombre π (pi) ≈ 3,141 59…","duration":"4 pages · animé","bilan":false,"competence":5,"familles":["Aire et périmètre d'un cercle"]},{"chapter":"Aires et figures","title":"Les unités","level":"6ème","desc":"Un périmètre est une longueur : on peut le parcourir, le mesurer au mètre ruban. Unité : mm, cm, m, km.","duration":"3 pages","bilan":false,"competence":6,"familles":["Aire et périmètre d'un rectangle"]},{"chapter":"Aires et figures","title":"Résoudre un problème","level":"6ème","desc":"Une chambre de 4 m × 3,5 m. La moquette coûte 12 € le m². Prix ? On recouvre une surface : c'est l'aire. 4 × 3,5 = 14 m². Prix : 14 × 12 = 168 €.","duration":"3 pages","bilan":false,"competence":7,"familles":["La chambre à moquette"]},{"chapter":"Aires et figures","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Repérage temps & durées","title":"Vue d'ensemble","level":"6ème–5ème","desc":"Le temps ne se compte pas en base 10 : soixante secondes font une minute, soixante minutes une heure, vingt-quatre heures un jour. Ce livre apprend à convertir, à calculer une durée ou une heure d'arrivée, et à ne plus confondre 1,5 h et 1 h 50.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Repérage temps & durées","title":"Les unités de temps","level":"6ème","desc":"1 jour = 24 heures. 1 heure = 60 minutes. 1 minute = 60 secondes. Ces nombres viennent des Babyloniens, qui comptaient en base 60 : 60 se divise par 2, 3, 4, 5, 6, 10, 12, 15, 20 et 30, ce qui rend les partages faciles.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Les unités de temps","Convertir des durées"]},{"chapter":"Repérage temps & durées","title":"Calculer une durée","level":"6ème","desc":"Un film commence à 14 h 25 et finit à 16 h 10. Durée ? Soustraire 14 h 25 de 16 h 10 colonne par colonne est piégeux (10 − 25 ?).","duration":"4 pages","bilan":false,"competence":2,"familles":["Calculer une durée"]},{"chapter":"Repérage temps & durées","title":"Calculer une heure d'arrivée","level":"6ème–5ème","desc":"Le bus part à 8 h 50 et roule 1 h 25. Arrivée ? On additionne heures et minutes séparément : 8 + 1 = 9 h, 50 + 25 = 75 min.","duration":"3 pages · animé","bilan":false,"competence":3,"familles":["Calculer une heure d'arrivée","L'arrivée du bus"]},{"chapter":"Repérage temps & durées","title":"Heures décimales","level":"5ème","desc":"Une calculatrice dit qu'un trajet dure 2,4 h. La partie décimale, 0,4, est une fraction d'heure : 0,4 h = 0,4 × 60 min = 24 min. Donc 2,4 h = 2 h 24 min.","duration":"3 pages","bilan":false,"competence":4,"familles":["Heures décimales"]},{"chapter":"Repérage temps & durées","title":"Résoudre un problème","level":"6ème","desc":"Le marathon en relais : trois coureurs mettent 1 h 12, 58 min et 1 h 05. Temps total ?","duration":"3 pages","bilan":false,"competence":5,"familles":["Le marathon en relais"]},{"chapter":"Repérage temps & durées","title":"Bilan du chapitre","level":"6ème–5ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Arithmétique","title":"Vue d'ensemble","level":"6ème–3ème","desc":"Répartir 157 élèves dans des cars, faire des lots identiques avec 48 stylos et 36 gommes, savoir quand deux guirlandes clignoteront ensemble : l'arithmétique, c'est la science des entiers, de leurs diviseurs et de leurs multiples. Ce livre va de la division euclidienne aux nombres premiers et au PGCD.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Arithmétique","title":"La division euclidienne","level":"6ème","desc":"194 œufs à ranger dans des boîtes de 12. Combien de boîtes pleines, et combien d'œufs restent ? 12 × 16 = 192, et 194 − 192 = 2. Seize boîtes pleines, deux œufs en trop.","duration":"4 pages","bilan":false,"competence":1,"familles":["Vocabulaire de la division euclidienne","Poser une division euclidienne","Les œufs en boîtes"]},{"chapter":"Arithmétique","title":"Les critères de divisibilité","level":"6ème","desc":"Un nombre est divisible par 2 s'il est pair : son dernier chiffre est 0, 2, 4, 6 ou 8. Par 5 : dernier chiffre 0 ou 5. Par 10 : dernier chiffre 0.","duration":"4 pages","bilan":false,"competence":2,"familles":["Critères de divisibilité"]},{"chapter":"Arithmétique","title":"Diviseurs et multiples communs","level":"4ème","desc":"12 = 3 × 4. On dit que 3 est un diviseur de 12, et que 12 est un multiple de 3. Les deux phrases disent la même chose.","duration":"4 pages","bilan":false,"competence":3,"familles":["Tous les diviseurs","Plus petit multiple commun","Les guirlandes synchronisées"]},{"chapter":"Arithmétique","title":"Les nombres premiers","level":"3ème","desc":"Un nombre premier a exactement deux diviseurs : 1 et lui-même. 7 est premier (diviseurs : 1, 7). 6 ne l'est pas (1, 2, 3, 6).","duration":"4 pages","bilan":false,"competence":4,"familles":["Premier ou non ?"]},{"chapter":"Arithmétique","title":"Décomposer en facteurs premiers","level":"3ème","desc":"60 = 2 × 30 = 2 × 2 × 15 = 2 × 2 × 3 × 5. On a divisé par le plus petit premier possible à chaque étape, jusqu'à obtenir 1.","duration":"4 pages","bilan":false,"competence":5,"familles":["Décomposer"]},{"chapter":"Arithmétique","title":"PGCD et fraction irréductible","level":"3ème","desc":"PGCD(60 ; 84) : 60 = 2² × 3 × 5 et 84 = 2² × 3 × 7. Les briques communes : 2² et 3. PGCD = 2² × 3 = 12.","duration":"4 pages","bilan":false,"competence":6,"familles":["Fraction irréductible"]},{"chapter":"Arithmétique","title":"Résoudre un problème","level":"6ème–3ème","desc":"« Combien de cars ? », « combien de boîtes ? », « que reste-t-il ? » → division euclidienne, et on interprète le reste.","duration":"3 pages","bilan":false,"competence":7,"familles":["Les cars du voyage scolaire","Les lots identiques","Le dallage parfait"]},{"chapter":"Arithmétique","title":"Bilan du chapitre","level":"6ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Enchaînement d'opérations","title":"Vue d'ensemble","level":"6ème–4ème","desc":"Trois billets de 20 € plus un billet de 10 € : 3 × 20 + 10. Si on calcule de gauche à droite, on trouve 3 × 30 = 90 €, ce qui est faux. Un calcul à plusieurs opérations obéit à des priorités. Ce livre les explique, puis apprend à traduire une phrase en calcul et un calcul en phrase.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Enchaînement d'opérations","title":"Priorité de la multiplication et de la division","level":"6ème","desc":"Tu achètes 3 cahiers à 2 € et 1 stylo à 5 €. Total : 3 × 2 + 5. Si on lit de gauche à droite : 3 × 2 = 6, puis 6 + 5 = 11 €. Juste.","duration":"4 pages","bilan":false,"competence":1,"familles":["Priorité de la multiplication/division"]},{"chapter":"Enchaînement d'opérations","title":"Calculer avec des parenthèses","level":"6ème","desc":"Et si on veut vraiment calculer 5 + 3 d'abord, puis multiplier par 2 (par exemple deux lots contenant un stylo à 5 € et un cahier à 3 €) ? On l'écrit avec des parenthèses : (5 + 3) × 2 = 8 × 2 = 16.","duration":"4 pages","bilan":false,"competence":2,"familles":["Calcul avec parenthèses"]},{"chapter":"Enchaînement d'opérations","title":"Traduire une phrase par une expression","level":"5ème","desc":"« La somme de 3 et 4 » : 3 + 4. « La différence de 9 et 5 » : 9 − 5. « Le produit de 5 par 6 » : 5 × 6. « Le quotient de 20 par 4 » : 20 ÷ 4.","duration":"4 pages","bilan":false,"competence":3,"familles":["Traduire par une expression"]},{"chapter":"Enchaînement d'opérations","title":"Bilan du chapitre","level":"6ème–4ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Calcul littéral","title":"Vue d'ensemble","level":"5ème–3ème","desc":"Un programme de calcul qu'on applique à n'importe quel nombre, l'aire d'un rectangle dont on ne connaît pas encore la largeur, une formule de prix : dès qu'un nombre est inconnu ou peut changer, on le remplace par une lettre. Ce livre apprend à écrire, réduire, développer et factoriser des expressions avec des lettres.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Calcul littéral","title":"Le programme de calcul","level":"5ème","desc":"« Choisis un nombre. Multiplie-le par 3. Ajoute 5. » Avec 4 : 4 × 3 = 12, 12 + 5 = 17. Avec 10 : 35. Avec 0 : 5.","duration":"4 pages","bilan":false,"competence":1,"familles":["Le programme de calcul"]},{"chapter":"Calcul littéral","title":"Réduire une expression","level":"5ème–4ème","desc":"3 pommes + 2 pommes = 5 pommes. 3 pommes + 2 poires : on ne peut rien simplifier. En calcul littéral, c'est pareil : 3x + 2x = 5x, mais 3x + 2y reste 3x + 2y.","duration":"4 pages","bilan":false,"competence":2,"familles":["Réduction"]},{"chapter":"Calcul littéral","title":"Développer : la distributivité","level":"4ème","desc":"Un rectangle de largeur 3 et de longueur x + 4. Son aire : 3(x + 4). Coupe-le en deux rectangles : l'un de 3 par x (aire 3x), l'autre de 3 par 4 (aire 12). Aire totale : 3x + 12.","duration":"4 pages","bilan":false,"competence":3,"familles":["Distributivité"]},{"chapter":"Calcul littéral","title":"Factoriser avec un facteur commun","level":"4ème–3ème","desc":"Développer : 3(x + 4) → 3x + 12. Factoriser : 3x + 12 → 3(x + 4). On transforme une somme en produit, en mettant en évidence ce qui est commun aux termes.","duration":"4 pages","bilan":false,"competence":4,"familles":["Factoriser"]},{"chapter":"Calcul littéral","title":"Les identités remarquables","level":"3ème","desc":"Un carré de côté a + b. Coupe-le : un carré a × a, un carré b × b, et deux rectangles a × b. Aire totale : a² + 2ab + b².","duration":"4 pages","bilan":false,"competence":5,"familles":["Développer (a−b)² et (a+b)²","Développer (a+b)(a−b)","Factoriser a²−b²"]},{"chapter":"Calcul littéral","title":"Le calcul malin","level":"3ème","desc":"102 × 98 : écris 102 = 100 + 2 et 98 = 100 − 2. Alors 102 × 98 = (100 + 2)(100 − 2) = 100² − 2² = 10 000 − 4 = 9 996. Sans poser.","duration":"3 pages","bilan":false,"competence":6,"familles":["Le calcul malin"]},{"chapter":"Calcul littéral","title":"Résoudre un problème","level":"4ème","desc":"Un panneau rectangulaire a une largeur inconnue x, et une longueur qui dépasse la largeur de 3 : x + 3. Son aire : x(x + 3) = x² + 3x. Son périmètre : 2(x + x + 3) = 4x + 6.","duration":"3 pages","bilan":false,"competence":7,"familles":["L'aire du panneau"]},{"chapter":"Calcul littéral","title":"Bilan du chapitre","level":"5ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"5 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Équations","title":"Vue d'ensemble","level":"4ème–3ème","desc":"« J'ai pensé à un nombre, je l'ai multiplié par 3, j'ai ajouté 5, j'ai trouvé 20. Quel est mon nombre ? » Une équation est une balance en équilibre avec une inconnue dessus. Ce livre apprend à la faire pencher, à isoler l'inconnue, et à vérifier.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Équations","title":"Vérifier une solution","level":"4ème","desc":"3x + 5 = 20 est une équation : une égalité avec une inconnue, x. Elle n'est pas vraie pour n'importe quel x. Pour x = 2 : 3 × 2 + 5 = 11 ≠ 20. Faux. Pour x = 5 : 3 × 5 + 5 = 20. Vrai.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Vérification des équations"]},{"chapter":"Équations","title":"Résoudre une équation simple","level":"4ème","desc":"2x + 3 = 7. Imagine une balance : à gauche, deux paquets identiques de masse inconnue x et une masse de 3 kg ; à droite, 7 kg. Elle est en équilibre.","duration":"5 pages","bilan":false,"competence":2,"familles":["Équations simples"]},{"chapter":"Équations","title":"Des x des deux côtés","level":"4ème","desc":"5x + 2 = 2x + 14 : des paquets x sur les deux plateaux. On en enlève 2 de chaque côté : 3x + 2 = 14. Toujours l'équilibre.","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Équations complexes"]},{"chapter":"Équations","title":"Équations avec parenthèses","level":"4ème","desc":"2(x + 1) = 5x − 7. Tant qu'il y a des parenthèses, on ne voit pas les x. On développe : 2x + 2 = 5x − 7.","duration":"3 pages","bilan":false,"competence":4,"familles":["Équations avec parenthèses"]},{"chapter":"Équations","title":"Équations avec des x²","level":"4ème–3ème","desc":"x² = 16. Quel nombre a pour carré 16 ? 4, bien sûr. Mais aussi −4, car (−4) × (−4) = 16.","duration":"4 pages","bilan":false,"competence":5,"familles":["Équations avec des x²"]},{"chapter":"Équations","title":"Bilan du chapitre","level":"4ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Géométrie","title":"Vue d'ensemble","level":"6ème","desc":"Un rail de chemin de fer, le bord d'une règle, la trajectoire d'un laser : la géométrie commence par nommer précisément ce qu'on voit. Ce livre installe le vocabulaire et les notations, les droites perpendiculaires et parallèles, puis le codage des figures, sur lesquels tout le reste s'appuie.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Géométrie","title":"Droite, segment, demi-droite","level":"6ème","desc":"Une droite est illimitée des deux côtés : on n'en dessine qu'un morceau, mais elle continue. Un rail de chemin de fer à perte de vue en donne l'idée. Notation : (AB), avec des parenthèses, si elle passe par A et B.","duration":"4 pages","bilan":false,"competence":1,"familles":["Droite, segment, demi-droite"]},{"chapter":"Géométrie","title":"Perpendiculaires et parallèles","level":"6ème","desc":"Deux droites qui se coupent en formant un angle droit sont perpendiculaires. Un mur et le sol, les deux traits d'une croix « + ». Notation : (d) ⊥ (d′). On code l'angle droit par un petit carré.","duration":"5 pages","bilan":false,"competence":2,"familles":["Perpendiculaires et parallèles"]},{"chapter":"Géométrie","title":"Le vocabulaire des figures","level":"6ème","desc":"Sur une figure, on ne mesure pas : on lit. Un petit carré dans un angle signifie « angle droit ». Deux segments marqués d'un même trait (ou double trait) ont la même longueur. Deux angles marqués d'un même arc sont égaux.","duration":"4 pages","bilan":false,"competence":3,"familles":["Vocabulaire des figures"]},{"chapter":"Géométrie","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Symétrie axiale","title":"Vue d'ensemble","level":"6ème","desc":"Un papillon, un visage, un reflet dans l'eau : la symétrie axiale est un pliage. Ce livre montre ce qui se passe quand on plie, apprend à construire le symétrique d'un point puis d'une figure, et explique ce que la symétrie conserve.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Symétrie axiale","title":"Construire le symétrique d'un point","level":"6ème","desc":"Trace une droite (d) sur une feuille, un point A d'un côté, et plie la feuille le long de (d). Le point A s'imprime de l'autre côté : c'est son symétrique A′.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Construction des symétries"]},{"chapter":"Symétrie axiale","title":"Les propriétés de la symétrie axiale","level":"6ème","desc":"Quand on plie, la figure ne se déforme pas : la symétrie axiale conserve les longueurs, les angles, les aires et l'alignement. L'image d'un triangle est un triangle superposable au premier.","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Construction des symétries"]},{"chapter":"Symétrie axiale","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Symétrie centrale","title":"Vue d'ensemble","level":"5ème","desc":"Une carte à jouer, un S, une hélice à deux pales : ces figures se retrouvent identiques après un demi-tour. La symétrie centrale est ce demi-tour autour d'un point. Ce livre apprend à la construire et à utiliser ses propriétés, dont le parallélisme.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Symétrie centrale","title":"Construire le symétrique d'un point","level":"5ème","desc":"Pique une punaise en O sur un calque posé sur la figure, et fais tourner le calque d'un demi-tour (180°). Le point A arrive en A′ : c'est son symétrique par rapport à O.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Construction des symétries"]},{"chapter":"Symétrie centrale","title":"Les propriétés de la symétrie centrale","level":"5ème","desc":"Un demi-tour ne déforme pas : la symétrie centrale conserve les longueurs, les angles, les aires, l'alignement. L'image d'un triangle est un triangle superposable.","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Construction des symétries"]},{"chapter":"Symétrie centrale","title":"Bilan du chapitre","level":"5ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Angles et parallélisme","title":"Vue d'ensemble","level":"5ème","desc":"Deux rues parallèles traversées par une avenue en biais forment huit angles… et on n'en mesure qu'un seul pour connaître les sept autres. Ce livre apprend à repérer les paires d'angles (opposés, complémentaires, supplémentaires, alternes-internes, correspondants) et à s'en servir dans les deux sens : calculer un angle, ou prouver que deux droites sont parallèles.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Angles et parallélisme","title":"Angles opposés par le sommet","level":"5ème","desc":"Deux droites sécantes forment quatre angles autour de leur point d'intersection. Deux angles face à face, qui n'ont en commun que leur sommet, sont opposés par le sommet : comme les deux lames d'une paire de ciseaux.","duration":"4 pages","bilan":false,"competence":1,"familles":["Angles opposés par le sommet"]},{"chapter":"Angles et parallélisme","title":"Angles complémentaires et supplémentaires","level":"5ème","desc":"Deux angles sont complémentaires si leur somme fait 90° : ils se complètent en un angle droit. 37° et 53°, 30° et 60°, 45° et 45°.","duration":"4 pages","bilan":false,"competence":2,"familles":["Complémentaires et supplémentaires"]},{"chapter":"Angles et parallélisme","title":"Angles alternes-internes","level":"5ème","desc":"Une droite (la sécante) traverse deux droites (d) et (d′). Elle forme quatre angles à chaque croisement, huit en tout.","duration":"4 pages","bilan":false,"competence":3,"familles":["Angles alternes-internes"]},{"chapter":"Angles et parallélisme","title":"Angles correspondants","level":"5ème","desc":"Deux angles sont correspondants s'ils sont du MÊME côté de la sécante et à la même position par rapport à leur droite : l'un « en haut à droite » du premier croisement, l'autre « en haut à droite » du second. Ils forment un « F ».","duration":"4 pages","bilan":false,"competence":4,"familles":["Angles correspondants"]},{"chapter":"Angles et parallélisme","title":"Déduire un angle","level":"5ème","desc":"(d) ∥ (d′). Un angle mesure 131°. Pour trouver n'importe quel autre, on enchaîne : son correspondant vaut 131° ; le supplémentaire de celui-ci vaut 49° ; l'opposé de ce dernier vaut 49°.","duration":"4 pages","bilan":false,"competence":5,"familles":["Déduire un angle"]},{"chapter":"Angles et parallélisme","title":"Bilan du chapitre","level":"5ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Géométrie du triangle","title":"Vue d'ensemble","level":"5ème","desc":"Le triangle est la figure la plus solide : une charpente, un pylône, un pont sont faits de triangles, parce qu'un triangle dont on connaît les trois côtés ne peut pas se déformer. Ce livre apprend à reconnaître les triangles, à savoir s'ils existent, et à calculer leurs angles.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Géométrie du triangle","title":"Les types de triangle","level":"5ème","desc":"Un triangle a trois côtés et trois angles. Selon ce qu'on sait d'eux, on le range dans une famille.","duration":"4 pages","bilan":false,"competence":1,"familles":["Types de triangle"]},{"chapter":"Géométrie du triangle","title":"Un triangle est-il constructible ?","level":"5ème","desc":"Pour aller de A à B, le plus court est la ligne droite. Passer par C est toujours plus long, ou au mieux aussi long (si C est sur le segment).","duration":"4 pages","bilan":false,"competence":2,"familles":["Triangle constructible ?"]},{"chapter":"Géométrie du triangle","title":"Le triangle quelconque : somme des angles","level":"5ème","desc":"Découpe un triangle en papier, arrache ses trois coins, et pose-les côte à côte : ils forment exactement un angle plat. Dans tout triangle, la somme des trois angles vaut 180°.","duration":"4 pages","bilan":false,"competence":3,"familles":["Triangle quelconque"]},{"chapter":"Géométrie du triangle","title":"Le triangle isocèle","level":"5ème–6ème","desc":"Dans un triangle isocèle, les angles à la base (opposés aux côtés égaux) sont égaux. Un triangle isocèle a un axe de symétrie : la médiatrice de la base, qui passe par le sommet principal. Le pliage échange les deux angles à la base.","duration":"4 pages","bilan":false,"competence":4,"familles":["Triangle isocèle"]},{"chapter":"Géométrie du triangle","title":"Le triangle rectangle","level":"5ème","desc":"Dans un triangle rectangle, l'angle droit vaut 90°. Comme la somme fait 180°, les deux autres angles totalisent 90° : ils sont complémentaires.","duration":"4 pages","bilan":false,"competence":5,"familles":["Triangle rectangle"]},{"chapter":"Géométrie du triangle","title":"Bilan du chapitre","level":"5ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Théorème de Pythagore","title":"Vue d'ensemble","level":"4ème–3ème","desc":"Une échelle contre un mur, la diagonale d'un écran, le fil qui retient un mât, la corde à 13 nœuds des maçons : partout où il y a un angle droit, les trois côtés sont liés par une seule égalité. Ce livre montre d'où elle vient, puis l'utilise pour calculer, prouver, et réfuter.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Théorème de Pythagore","title":"Repérer l'hypoténuse et énoncer le théorème","level":"4ème","desc":"Un triangle rectangle a un angle droit. Le côté qui lui fait face, celui qui ne touche pas l'angle droit, s'appelle l'hypoténuse. C'est toujours le plus long des trois.","duration":"5 pages · animé","bilan":false,"competence":1,"familles":["Le fil du mât"]},{"chapter":"Théorème de Pythagore","title":"Calculer l'hypoténuse","level":"4ème","desc":"Un mât de 4 m est tenu par un fil fixé au sol à 3 m du pied du mât. Le mât est vertical, le sol horizontal : angle droit au pied du mât. Le fil est l'hypoténuse.","duration":"5 pages · animé","bilan":false,"competence":2,"familles":["Le fil du mât","La diagonale de l'écran"]},{"chapter":"Théorème de Pythagore","title":"Calculer un côté de l'angle droit","level":"4ème–3ème","desc":"Une échelle de 13 m est posée contre un mur, son pied à 5 m du mur. À quelle hauteur touche-t-elle le mur ?","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Calculer un côté de l'angle droit"]},{"chapter":"Théorème de Pythagore","title":"Réciproque et contraposée","level":"3ème","desc":"Un triangle a pour côtés 5, 12 et 13 cm. Est-il rectangle ? On ne peut pas se fier au dessin : on calcule.","duration":"5 pages","bilan":false,"competence":4,"familles":["Démontrer avec la contraposée"]},{"chapter":"Théorème de Pythagore","title":"Résoudre un problème","level":"3ème","desc":"Dans un problème, l'angle droit n'est pas toujours annoncé. Il se cache dans : un mur et le sol, les bords d'un rectangle, une hauteur et une base, le nord et l'est, le rayon d'un cercle et sa tangente.","duration":"3 pages","bilan":false,"competence":5,"familles":["La diagonale de l'écran","Le fil du mât"]},{"chapter":"Théorème de Pythagore","title":"Bilan du chapitre","level":"4ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Théorème de Thalès","title":"Vue d'ensemble","level":"3ème","desc":"Un bâton et un arbre plantés au soleil ont des ombres proportionnelles à leurs hauteurs. Deux droites parallèles coupées par deux sécantes créent toujours des longueurs proportionnelles : c'est le théorème de Thalès. Ce livre part de l'ombre, explique la configuration, puis utilise le théorème dans les deux sens.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Théorème de Thalès","title":"Triangles imbriqués","level":"3ème","desc":"Un bâton de 1 m planté dans le sol fait une ombre de 1,5 m. Au même moment, un arbre fait une ombre de 9 m. Quelle est la hauteur de l'arbre ?","duration":"5 pages · animé","bilan":false,"competence":1,"familles":["Triangles imbriqués"]},{"chapter":"Théorème de Thalès","title":"Triangles opposés (le papillon)","level":"3ème","desc":"Deux droites se coupent en A. B et M sont sur la première, de part et d'autre de A ; C et N sur la seconde, de part et d'autre de A. Et (BC) ∥ (MN).","duration":"4 pages","bilan":false,"competence":2,"familles":["Triangles opposés"]},{"chapter":"Théorème de Thalès","title":"La réciproque de Thalès","level":"3ème","desc":"Le théorème dit : si les droites sont parallèles, alors les rapports sont égaux. La réciproque va dans l'autre sens : si les rapports sont égaux, alors les droites sont parallèles.","duration":"4 pages","bilan":false,"competence":3,"familles":["Démonstration avec la réciproque de Thalès"]},{"chapter":"Théorème de Thalès","title":"Triangles semblables","level":"3ème","desc":"Deux triangles sont semblables quand ils ont les mêmes angles. L'un est l'agrandissement (ou la réduction) de l'autre : même forme, pas la même taille.","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Triangles semblables"]},{"chapter":"Théorème de Thalès","title":"Bilan du chapitre","level":"3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Trigonométrie","title":"Vue d'ensemble","level":"4ème–3ème","desc":"La pente d'une rampe, la hauteur d'une tour mesurée depuis le trottoir, l'inclinaison d'une échelle pour qu'elle ne glisse pas : dans un triangle rectangle, un angle et deux côtés sont toujours liés. Ce livre explique d'où viennent le cosinus, le sinus et la tangente, et comment s'en servir.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Trigonométrie","title":"Repérer les côtés par rapport à un angle","level":"4ème","desc":"Dans un triangle rectangle, l'hypoténuse ne change jamais : c'est le côté en face de l'angle droit, le plus long.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Calculer un côté avec le cosinus"]},{"chapter":"Trigonométrie","title":"Le cosinus","level":"4ème","desc":"Le cosinus d'un angle aigu est le rapport : adjacent ÷ hypoténuse. On note cos(angle).","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Calculer un côté avec le cosinus","Calculer un angle avec le cosinus"]},{"chapter":"Trigonométrie","title":"Le sinus","level":"3ème","desc":"Le sinus d'un angle aigu est le rapport : opposé ÷ hypoténuse. On note sin(angle).","duration":"4 pages","bilan":false,"competence":3,"familles":["Calculer une longueur avec le sinus","Calculer un angle avec le sinus"]},{"chapter":"Trigonométrie","title":"La tangente","level":"3ème","desc":"La tangente d'un angle aigu est le rapport : opposé ÷ adjacent. On note tan(angle). C'est la seule des trois formules qui n'utilise pas l'hypoténuse.","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Calculer une longueur avec la tangente","Calculer un angle avec la tangente"]},{"chapter":"Trigonométrie","title":"Résoudre un problème","level":"3ème","desc":"Une rampe pour fauteuils roulants monte de 1 m sur 10 m de longueur au sol. Quel est son angle avec le sol ?","duration":"3 pages · animé","bilan":false,"competence":5,"familles":["L'angle de la rampe"]},{"chapter":"Trigonométrie","title":"Bilan du chapitre","level":"4ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Homothéties","title":"Vue d'ensemble","level":"3ème","desc":"Un projecteur qui agrandit une diapositive sur un mur, une photocopie à 50 %, un zoom sur un plan : l'homothétie agrandit ou réduit une figure depuis un point fixe, en gardant sa forme. Ce livre apprend à la construire et à prévoir son effet sur les longueurs et les aires.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Homothéties","title":"Construire l'image par une homothétie","level":"3ème","desc":"Une lampe en O éclaire une petite figure ; son ombre sur le mur est une figure agrandie, de même forme. Chaque point M de la figure envoie son ombre M′ dans le prolongement du rayon [OM).","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Construction des homothéties"]},{"chapter":"Homothéties","title":"Les propriétés","level":"3ème","desc":"Une homothétie de rapport 3 triple toutes les longueurs : un côté de 2 cm devient 6 cm, un cercle de rayon 1 devient un cercle de rayon 3.","duration":"4 pages","bilan":false,"competence":2,"familles":["Construction des homothéties"]},{"chapter":"Homothéties","title":"Bilan du chapitre","level":"3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Translation et rotation","title":"Vue d'ensemble","level":"4ème","desc":"Un tiroir qu'on tire, un ascenseur qui monte : une translation. Une porte qui pivote, une aiguille de montre, une grande roue : une rotation. Deux déplacements qui ne déforment rien. Ce livre apprend à les construire et à reconnaître ce qu'ils conservent.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Translation et rotation","title":"La translation","level":"4ème","desc":"Pousse un livre sur la table, tout droit, sans le tourner : chaque point du livre s'est déplacé de la même distance, dans la même direction et le même sens. C'est une translation.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Rotation et translation"]},{"chapter":"Translation et rotation","title":"La rotation","level":"4ème","desc":"Une porte pivote autour de ses gonds ; l'aiguille d'une montre autour du centre du cadran. C'est une rotation : elle est définie par un CENTRE O, un ANGLE et un SENS (horaire, comme les aiguilles, ou anti-horaire).","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Rotation et translation"]},{"chapter":"Translation et rotation","title":"Ce qui est conservé","level":"4ème","desc":"Translation et rotation conservent les longueurs, les angles, les aires, l'alignement, le parallélisme et les milieux : la figure image est superposable à la figure de départ, c'est la même figure posée ailleurs.","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Rotation et translation"]},{"chapter":"Translation et rotation","title":"Bilan du chapitre","level":"4ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Volumes et solides","title":"Vue d'ensemble","level":"6ème–3ème","desc":"Combien de litres dans un aquarium, de béton dans un pilier, d'air dans un ballon ? Ce livre apprend à reconnaître les solides usuels et à calculer leur volume, avec une seule idée à retenir : aire de la base fois hauteur, divisée par trois pour les solides pointus.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Volumes et solides","title":"Reconnaître un solide","level":"6ème–3ème","desc":"Les solides « droits » : deux bases parallèles et identiques, reliées par des faces verticales. Si la base est un polygone, c'est un prisme droit (le cube et le pavé droit sont des prismes à base rectangulaire). Si la base est un disque, c'est un cylindre.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Reconnaître un solide"]},{"chapter":"Volumes et solides","title":"Volume du cube et du pavé droit","level":"6ème","desc":"Un pavé de 5 cm × 3 cm × 2 cm. Remplis-le de cubes de 1 cm d'arête : 5 × 3 = 15 cubes par couche, 2 couches, 30 cubes. Son volume est 30 cm³.","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Volume d'un cube","Volume d'un pavé droit"]},{"chapter":"Volumes et solides","title":"Volume du prisme et du cylindre","level":"5ème","desc":"Un prisme ou un cylindre, c'est une base qu'on « empile » sur une hauteur. Le volume est l'aire de la base multipliée par la hauteur : V = B × h. Le pavé n'était qu'un cas particulier (base rectangulaire).","duration":"4 pages","bilan":false,"competence":3,"familles":["Volume d'un prisme droit","Volume d'un cylindre"]},{"chapter":"Volumes et solides","title":"Volume de la pyramide et du cône","level":"4ème","desc":"Remplis une pyramide d'eau et verse-la dans le prisme de même base et de même hauteur : il faut trois pyramides pour le remplir. Même chose pour un cône et un cylindre.","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Volume d'une pyramide","Volume d'un cône"]},{"chapter":"Volumes et solides","title":"Volume de la boule","level":"3ème","desc":"Une boule de rayon r a pour volume V = (4/3) × π × r³. On ne la retrouve pas par découpage simple : on l'admet, elle a été démontrée par Archimède.","duration":"4 pages","bilan":false,"competence":5,"familles":["Volume d'une boule"]},{"chapter":"Volumes et solides","title":"Bilan du chapitre","level":"6ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Notions de fonctions","title":"Vue d'ensemble","level":"3ème","desc":"Un distributeur : on met une pièce, un objet sort. Une fonction, c'est pareil : on entre un nombre, un nombre sort, toujours le même pour la même entrée. Ce livre installe le vocabulaire (image, antécédent), la notation, et les trois façons de décrire une fonction : une formule, un tableau, une courbe.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Notions de fonctions","title":"La notation « flèche »","level":"3ème","desc":"Le tarif d'un parking : 3 € par heure, moins 2 € de réduction avec un ticket de cinéma. Pour x heures, on paie 3x − 2 euros. À chaque durée correspond un prix, et un seul.","duration":"4 pages","bilan":false,"competence":1,"familles":["La notation « flèche »"]},{"chapter":"Notions de fonctions","title":"Calculer une image","level":"3ème","desc":"L'image de a par f est f(a) : ce qui sort quand on entre a. Pour la calculer, on remplace CHAQUE x de la formule par a, et on applique les priorités.","duration":"4 pages","bilan":false,"competence":2,"familles":["Calculer une image","Image d'un nombre négatif","Une fonction avec un carré"]},{"chapter":"Notions de fonctions","title":"Déterminer un antécédent","level":"3ème","desc":"Un antécédent de b par f est un nombre x tel que f(x) = b : une entrée qui donne la sortie b. Chercher un antécédent, c'est remonter la machine.","duration":"4 pages","bilan":false,"competence":3,"familles":["Déterminer un antécédent"]},{"chapter":"Notions de fonctions","title":"Lire un tableau de valeurs","level":"3ème","desc":"Une formule : f(x) = 3x − 2. Un tableau de valeurs : des entrées en haut, leurs images en bas. Une courbe : chaque point a pour coordonnées (x ; f(x)).","duration":"4 pages · animé","bilan":false,"competence":4,"familles":["Le tableau mystère"]},{"chapter":"Notions de fonctions","title":"Bilan du chapitre","level":"3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Fonction linéaire","title":"Vue d'ensemble","level":"3ème","desc":"Le prix au kilo, le taux de change, la vitesse constante : la proportionnalité, vue comme une fonction. f(x) = ax : on multiplie l'entrée par un nombre fixe. Sa courbe est une droite qui passe par l'origine. Ce livre relie ce que tu sais de la proportionnalité à ce nouveau langage.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Fonction linéaire","title":"Reconnaître une fonction linéaire","level":"3ème","desc":"Les cerises coûtent 6 € le kilo. Pour x kilos, on paie 6x euros. La fonction prix : f(x) = 6x. C'est une fonction linéaire : f(x) = a × x, avec a = 6.","duration":"4 pages","bilan":false,"competence":1,"familles":["Reconnaître une fonction linéaire"]},{"chapter":"Fonction linéaire","title":"Image et antécédent","level":"3ème","desc":"f(x) = −2x. Image de 5 : f(5) = −2 × 5 = −10. Une multiplication.","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["Image et antécédent"]},{"chapter":"Fonction linéaire","title":"Déterminer le coefficient","level":"3ème","desc":"f est linéaire et f(4) = 6. Alors 4a = 6, donc a = 6 ÷ 4 = 1,5, et f(x) = 1,5x.","duration":"4 pages","bilan":false,"competence":3,"familles":["Déterminer le coefficient"]},{"chapter":"Fonction linéaire","title":"Résoudre un problème","level":"3ème","desc":"1 € vaut 1,10 $. Pour convertir x euros en dollars : f(x) = 1,10x. C'est une fonction linéaire de coefficient 1,10 (le taux).","duration":"3 pages · animé","bilan":false,"competence":4,"familles":["Le taux de change"]},{"chapter":"Fonction linéaire","title":"Bilan du chapitre","level":"3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Fonction affine","title":"Vue d'ensemble","level":"3ème","desc":"Un abonnement plus un prix à la minute, un taxi avec prise en charge, un plombier avec déplacement : une part fixe plus une part proportionnelle. f(x) = ax + b. Sa courbe est une droite qui ne passe plus par l'origine. Ce livre apprend à lire a et b, à calculer dans les deux sens, et à retrouver une fonction affine à partir de deux points.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Fonction affine","title":"Identifier a et b","level":"3ème","desc":"Forfait téléphone : 10 € par mois, plus 0,05 € par minute. Pour x minutes : f(x) = 0,05x + 10. Même sans appeler, on paie 10 €.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Identifier a et b"]},{"chapter":"Fonction affine","title":"Calculer des images","level":"3ème","desc":"f(x) = −3x + 7. f(2) = −3 × 2 + 7 = −6 + 7 = 1. La multiplication avant l'addition, comme toujours.","duration":"4 pages","bilan":false,"competence":2,"familles":["Calculer des images"]},{"chapter":"Fonction affine","title":"Déterminer un antécédent","level":"3ème","desc":"Antécédent de 9 par f(x) = 2x + 1 : on résout 2x + 1 = 9. On enlève b : 2x = 8. On divise par a : x = 4.","duration":"4 pages","bilan":false,"competence":3,"familles":["Antécédent par une fonction affine"]},{"chapter":"Fonction affine","title":"Déterminer une fonction affine","level":"3ème","desc":"Une fonction affine est une droite ; deux points déterminent une droite. Donc deux couples (x ; f(x)) suffisent à retrouver a et b.","duration":"4 pages","bilan":false,"competence":4,"familles":["Déterminer une fonction affine"]},{"chapter":"Fonction affine","title":"Résoudre un problème","level":"3ème","desc":"Tout tarif « part fixe + prix unitaire » est une fonction affine : b est la part fixe, a le prix unitaire. Forfait : f(x) = 0,05x + 10. Taxi : t(x) = 1,5x + 4. Location de vélo : 5 € puis 2 € de l'heure, v(x) = 2x + 5.","duration":"3 pages","bilan":false,"competence":5,"familles":["Le forfait téléphonique"]},{"chapter":"Fonction affine","title":"Bilan du chapitre","level":"3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Bases des probabilités","title":"Vue d'ensemble","level":"5ème–3ème","desc":"On ne sait pas quel côté d'une pièce va tomber. Mais on sait qu'à la longue, ce sera pile une fois sur deux. Le hasard a des règles. Ce livre part du dé, de la pièce, de l'urne et de la roue de kermesse pour construire la probabilité, l'événement contraire, et les expériences à deux étapes.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Bases des probabilités","title":"Les issues d'une expérience","level":"5ème","desc":"On lance un dé à six faces. On ne sait pas ce qui va sortir, mais on sait tout ce qui PEUT sortir : 1, 2, 3, 4, 5 ou 6. Chacun de ces résultats est une issue. L'ensemble des issues est l'univers : {1, 2, 3, 4, 5, 6}.","duration":"4 pages · animé","bilan":false,"competence":1,"familles":["Les issues d'une expérience"]},{"chapter":"Bases des probabilités","title":"L'échelle des probabilités","level":"5ème–4ème","desc":"La probabilité d'un événement mesure sa chance de se produire : un nombre entre 0 et 1. 0 : impossible (obtenir 7 avec un dé). 1 : certain (obtenir moins de 7). 0,5 : une chance sur deux (pile).","duration":"4 pages · animé","bilan":false,"competence":2,"familles":["L'échelle des probabilités","La somme des probabilités"]},{"chapter":"Bases des probabilités","title":"Calculer la probabilité d'un événement","level":"5ème–4ème","desc":"Quand toutes les issues ont la même chance (dé équilibré, boules indiscernables au toucher, roue à secteurs égaux), on dit qu'il y a équiprobabilité. Alors : P(A) = nombre d'issues favorables à A ÷ nombre d'issues possibles.","duration":"4 pages · animé","bilan":false,"competence":3,"familles":["Probabilité d'un événement","Probabilité simple","Probabilité avec un dé","Tirage dans une urne","Le jeu de 32 cartes","La roue de la kermesse","Probabilité sur une roue","Les jetons numérotés"]},{"chapter":"Bases des probabilités","title":"L'événement contraire","level":"4ème–3ème","desc":"L'événement contraire de A, noté « non A », est réalisé exactement quand A ne l'est pas. Contraire de « tirer un as » : « ne pas tirer un as ». Contraire de « obtenir 6 » : « obtenir 1, 2, 3, 4 ou 5 ».","duration":"4 pages","bilan":false,"competence":4,"familles":["L'événement contraire"]},{"chapter":"Bases des probabilités","title":"De la fréquence à la probabilité","level":"3ème","desc":"Une punaise lancée retombe pointe en l'air ou sur le côté. Les deux issues n'ont pas la même chance, et rien ne permet de calculer : pas d'équiprobabilité, pas de formule.","duration":"4 pages","bilan":false,"competence":5,"familles":["De la fréquence à la probabilité"]},{"chapter":"Bases des probabilités","title":"Une expérience à deux épreuves","level":"3ème","desc":"On lance deux pièces. Résultat : un COUPLE, comme (pile, face). Les issues sont PP, PF, FP, FF : quatre, toutes équiprobables. Attention : PF et FP sont deux issues différentes (la première pièce n'est pas la seconde).","duration":"4 pages","bilan":false,"competence":6,"familles":["Dé et pièce","Deux pièces de monnaie","Deux tirages avec remise"]},{"chapter":"Bases des probabilités","title":"Bilan du chapitre","level":"5ème–3ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"4 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Organisation des données","title":"Vue d'ensemble","level":"6ème","desc":"Comment viennent les élèves au collège ? Un sondage, une liste de réponses en vrac, puis un tableau, puis un diagramme : les données brutes deviennent lisibles. Ce livre apprend à compter (effectifs), à comparer (fréquences), à lire et à construire les diagrammes.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Organisation des données","title":"Analyser des données","level":"6ème","desc":"On a demandé à 46 élèves comment ils viennent au collège. Les réponses arrivent en vrac : bus, vélo, à pied, bus, voiture… On les trie dans un tableau : bus 10, vélo 6, à pied 16, voiture 14.","duration":"4 pages","bilan":false,"competence":1,"familles":["Analyse de données"]},{"chapter":"Organisation des données","title":"Construire un diagramme","level":"6ème","desc":"Un bâton par catégorie, tous de même largeur, séparés. La hauteur est l'effectif, lue sur un axe vertical gradué régulièrement.","duration":"4 pages","bilan":false,"competence":2,"familles":["Construction"]},{"chapter":"Organisation des données","title":"Bilan du chapitre","level":"6ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"2 pages","bilan":true,"competence":0,"familles":[]},{"chapter":"Statistiques","title":"Vue d'ensemble","level":"5ème–4ème","desc":"Cinq notes, dix températures, mille salaires : comment résumer une série de nombres en un ou deux ? La moyenne, la médiane et l'étendue répondent chacune à une question différente. Ce livre explique laquelle choisir, et pourquoi la moyenne peut mentir.","duration":"2 pages","bilan":false,"competence":0,"familles":[]},{"chapter":"Statistiques","title":"La fréquence","level":"5ème","desc":"Dans une classe de 30 élèves, 18 pratiquent un sport. Effectif : 18. Fréquence : 18 ÷ 30 = 0,6, soit 60 %.","duration":"3 pages","bilan":false,"competence":1,"familles":["Fréquence"]},{"chapter":"Statistiques","title":"La moyenne","level":"4ème","desc":"Cinq amis ont 8, 11, 12, 14 et 15 billes. S'ils mettaient tout en commun et se partageaient équitablement, chacun aurait (8 + 11 + 12 + 14 + 15) ÷ 5 = 60 ÷ 5 = 12 billes. C'est la moyenne.","duration":"4 pages","bilan":false,"competence":2,"familles":["Calculer une moyenne"]},{"chapter":"Statistiques","title":"La moyenne pondérée","level":"5ème–3ème","desc":"Contrôle coefficient 3 : 14. Interro coefficient 1 : 8. Moyenne ? Le contrôle « compte triple » : c'est comme trois notes de 14 et une de 8. (14 + 14 + 14 + 8) ÷ 4 = 50 ÷ 4 = 12,5.","duration":"4 pages","bilan":false,"competence":3,"familles":["Moyenne pondérée"]},{"chapter":"Statistiques","title":"La médiane","level":"4ème","desc":"Salaires : 1 500, 1 600, 1 700, 1 800, 12 000. La moyenne (3 720) ne représente personne. Rangeons la série et prenons la valeur du MILIEU : 1 700. Deux salaires en dessous, deux au-dessus. C'est la médiane.","duration":"4 pages","bilan":false,"competence":4,"familles":["Médiane d'une série impaire","Médiane d'une série paire"]},{"chapter":"Statistiques","title":"L'étendue","level":"4ème","desc":"Deux classes ont 12 de moyenne. Dans la première, les notes vont de 10 à 14 ; dans la seconde, de 2 à 20. L'étendue mesure cet écart : maximum − minimum. Première classe : 4. Seconde : 18.","duration":"3 pages","bilan":false,"competence":5,"familles":["Calculer l'étendue"]},{"chapter":"Statistiques","title":"Bilan du chapitre","level":"5ème–4ème","desc":"Tous les « à retenir » et tous les pièges du chapitre, sur quelques pages.","duration":"3 pages","bilan":true,"competence":0,"familles":[]}];
